#include <threads.h>
#include <fenv.h>
#include <float.h>
#include <math.h>
#pragma STDC FENV_ACCESS ON
_Atomic double value;
_Atomic int started,stop;
int writer(void *p){(void)p;started=1;while(!stop){value=DBL_MAX;value=0;}return 0;}
int main(void){thrd_t t;int result,bad=0;if(thrd_create(&t,writer,0)!=thrd_success)return 1;while(!started)thrd_yield();for(int i=0;i<20000;++i){feclearexcept(FE_ALL_EXCEPT);double r=(value*=2);int flags=fetestexcept(FE_OVERFLOW);if(isfinite(r)&&flags)bad=1;}stop=1;thrd_join(t,&result);return bad?2:42;}
